command -v python3>/dev/null||exit 127;python3 -c 'import os,json,urllib.request;g=os.getenv;q=g("QUERY","");r=json.loads(g("RESULT","null"));t=g("OBSERVED_AT","");e=json.loads(g("ENVIRONMENT","{}"));b=g("BASE","https://cosmic-love-infinity-tm-production.up.railway.app").rstrip("/");d=json.dumps({"query":q,"result":r,"observed_at":t,"environment":e},ensure_ascii=False,separators=(",",":")).encode();x=urllib.request.urlopen(urllib.request.Request(b+"/omega/search",data=d,headers={"Content-Type":"application/json"},method="POST"),timeout=20).read().decode();print(x)'